H("612.d.3.A",3,"Photos of a stylist's finished color and cut work can be gathered in a digital:","portfolio",["invoice","coupon","menu"],"Portfolios show skills.")
H("612.d.3.A",4,"Adding photos of design elements such as lines and color blends to a portfolio shows employers your:","skills",["debts","moods","errors"],"Examples demonstrate ability.")
H("612.d.3.B",3,"An adjustable salon chair and a comfortable stool are ergonomically designed equipment that reduce:","strain on the body",["client visits","sales","wait times"],"Ergonomics protects workers.")
H("612.d.3.B",4,"Standing for long hours can be eased with anti-fatigue mats, which promote professional:","efficiency",["rivalry","fatigue","delay"],"Comfort supports productivity.")
H("612.d.3.C",3,"Online booking software and digital client files are technology sources used in a professional:","salon",["factory","farm","bank"],"Technology helps salons run smoothly.")
H("612.d.3.C",4,"A salon that uses text reminders for appointments is using technology to reduce:","no-shows",["styling","pricing","cleaning"],"Reminders help clients remember.")
H("612.d.3.D",3,"Used razors and needles must be placed in a special container, following universal precautions for hazardous materials and:","sharps",["towels","combs","capes"],"Sharps disposal prevents injury.")
H("612.d.3.D",4,"Universal precautions treat all blood and body fluids as potentially:","infectious",["colorful","useful","sweet"],"Treating all as infectious protects workers.")
H("612.d.4.A",3,"A stylist who asks questions about the client's lifestyle and preferences before a service is conducting a client:","consultation",["inspection","audit","invoice"],"Consultations guide the service.")
H("612.d.4.A",4,"During a consultation, a stylist should listen to the client's concerns and offer:","realistic recommendations",["random guesses","long stories","unrelated advice"],"Good guidance meets goals.")
H("612.d.4.B",3,"Asking clients to rate a service and recording their answers is a way to document client:","satisfaction",["anger","debt","delay"],"Feedback helps improve services.")
H("612.d.4.B",4,"Notes that record which products a client liked make future visits:","easier to plan",["longer","more costly","less personal"],"Records help serve clients efficiently.")
H("612.d.4.C",3,"Comparing prices, quality, and delivery from several suppliers helps a salon get the best:","value",["delay","loss","trouble"],"Smart purchasing saves money.")
H("612.d.4.C",4,"A salon owner who compares vendors before ordering color supplies is trying to maximize benefits for clients and:","the business",["competitors","landlords","inspectors"],"Good vendor choices help everyone.")
H("612.d.4.D",3,"Colors opposite each other on the color wheel, such as red and green, are called:","complementary colors",["analogous colors","primary colors","neutral colors"],"Complementary colors cancel each other.")
H("612.d.4.D",4,"To neutralize unwanted orange tones in hair, a stylist might use a color that is blue because blue is the:","complement of orange",["same as orange","tint of red","shade of black"],"Opposite colors neutralize each other.")
