H("612.d.4.F",4,"A temporary color rinse is designed to wash out after:","one or a few shampoos",["many years","one year","several months"],"Temporary colors fade quickly.")
H("612.d.4.G",3,"A product used to boost shine and keep a color vibrant between salon visits is a color:","gloss or shampoo for color-treated hair",["remover","strip","bleach"],"Aftercare keeps color fresh.")
H("612.d.4.G",4,"Using a violet-based product on blonde hair helps cancel unwanted:","yellow tones",["violet tones","blue tones","green tones"],"Violet is opposite yellow.")
H("612.d.4.H",3,"Henna and vegetable dyes are examples of:","natural coloring products",["synthetic bleaches","chemical relaxers","metallic dyes"],"These dyes come from plants.")
H("612.d.4.H",4,"A natural dye like henna typically coats the hair rather than:","lifting its natural color",["staining skin","drying","reddening"],"Natural dyes deposit color.")
H("612.d.5.A",3,"A salon that posts video tutorials and client results online is using multimedia to attract and keep:","clients",["inspectors","vendors","lenders"],"Marketing builds a client base.")
H("612.d.5.A",4,"The best multimedia for a salon's marketing depends on the target audience and the:","message",["weather","calendar","rent"],"Media should fit the audience and goal.")
H("612.d.5.B",3,"A salon service menu lists services and their:","prices",["rumors","colors","weights"],"Menus show what is offered and the cost.")
H("612.d.5.B",4,"A salon that sees growing demand for natural hair care might add services based on current industry:","trends",["rumors","errors","penalties"],"Menus should reflect trends.")
H("612.d.5.C",3,"Comment cards, online reviews, and follow-up calls are methods of obtaining client:","feedback",["debt","discounts","supplies"],"Feedback shows how clients feel.")
H("612.d.5.C",4,"Using feedback from clients to change a service is a way a salon can improve its:","quality",["rent","hours","exams"],"Feedback drives improvement.")
H("612.d.5.D",3,"An employment portfolio for a cosmetologist might include certifications, work samples, and:","references",["recipes","tax forms","receipts"],"Portfolios show credentials.")
H("612.d.5.D",4,"A resume and photos of your best work belong in a(n):","employment portfolio",["tax return","salon menu","client file"],"A portfolio helps in job interviews.")
H("612.d.5.E",3,"Professional organizations offer members training, networking, and:","industry updates",["free products only","guaranteed jobs","salary raises"],"Organizations keep professionals informed.")
H("612.d.5.E",4,"Joining a professional cosmetology association can help a stylist keep up with new:","techniques and laws",["fashions only","recipes","sports"],"Associations share information.")

# ---- 613 Consumer Services (Economics and Consumer Sciences) ----
H("613.d.1.A",3,"The right to be told the truth about a product's ingredients and cost is a consumer right to:","information",["profit","secrecy","luck"],"Consumers have the right to accurate information.")
H("613.d.1.A",4,"A consumer who reads a warranty before buying is exercising the responsibility to:","be informed",["complain only","borrow","return everything"],"Rights come with responsibilities.")
H("613.d.1.B",3,"Making a list of tasks, setting deadlines, and assigning time for each is an example of using planning skills to:","organize tasks",["avoid work","delay","guess"],"Planning helps organize responsibilities.")
H("613.d.1.B",4,"A family that schedules grocery trips, bill due dates, and chores on a shared calendar is applying:","management skills",["luck","debt","impulse"],"Management organizes tasks and resources.")
H("613.d.1.C",3,"A shopper who researches products, compares prices, and sets a spending limit is using strategies to make wise:","choices",["mistakes","trades","debts"],"Planning supports good decisions.")
H("613.d.1.C",4,"Waiting a day before making an unplanned purchase helps a consumer avoid:","impulse buying",["comparison shopping","budgeting","saving"],"Waiting reduces impulsive spending.")
H("613.d.1.D",3,"A person who buys a product on credit and misses payments may face a late fee and a lower credit score. These are the:","consequences of an economic decision",["benefits of saving","rewards of waiting","features of the product"],"Every economic choice has results.")
H("613.d.1.D",4,"Using a credit card to buy a $400 item and paying only the minimum each month usually leads to paying much more because of:","interest",["rebates","tips","coupons"],"Interest increases total cost.")
H("613.d.1.E",3,"Targeted ads that appear after you search for a product show the impact of technology and media on consumer:","decisions",["weather","history","travel"],"Advertising shapes buying choices.")
H("613.d.1.E",4,"Online reviews, influencers, and social media posts can all influence what a family decides to:","buy",["avoid learning","keep secret","forget"],"Media affects spending.")
H("613.d.2.A",3,"Creating a budget and building an emergency fund are parts of personal financial:","planning",["gambling","spending","debts"],"Planning helps families meet goals.")
H("613.d.2.A",4,"Experts often suggest keeping several months of expenses in an emergency fund to cover:","unexpected costs",["vacations","impulse buys","luxury items"],"Emergencies can be expensive.")
H("613.d.2.B",3,"A loan used to buy a house is called a:","mortgage",["credit card","debit card","payday loan"],"Mortgages finance home purchases.")
H("613.d.2.B",4,"A lender checks a borrower's credit history, income, and debts to decide if the person meets the criteria for a:","loan",["coupon","rebate","budget"],"Lenders assess risk.")
H("613.d.2.C",3,"Interest earned only on the original amount is called simple interest, while interest earned on the original amount plus past interest is called:","compound interest",["flat interest","loan interest","penalty interest"],"Compound interest grows faster.")
H("613.d.2.C",4,"How much simple interest is earned in one year on $1,000 at 5 percent?","$50",["$5","$500","$100"],"1,000 x 0.05 = 50.")
H("613.d.2.D",3,"The longer funds stay in a savings account earning interest, the more they grow. This is the time value of:","money",["goods","taxes","debts"],"Time makes savings grow.")
H("613.d.2.D",4,"Starting to save at age 20 rather than 40 generally results in a larger balance by retirement because of more time for:","compounding",["spending","loans","fees"],"Time boosts growth.")
H("613.d.2.E",3,"A prudent investor spreads money across different types of investments, which is called:","diversification",["gambling","speculation","borrowing"],"Diversifying reduces risk.")
H("613.d.2.E",4,"Stocks generally carry more risk but have a higher chance of growth than:","savings accounts",["lottery tickets","penny stocks","speculation"],"Risk and return are related.")
H("613.d.2.F",3,"Donating money or time to a nonprofit is called:","charitable giving",["investing","borrowing","spending"],"Giving helps others.")
H("613.d.2.F",4,"A benefit of charitable giving to a taxpayer can be a possible:","tax deduction",["penalty","fee","loan"],"Some gifts reduce taxable income.")
H("613.d.2.G",3,"A financial institution owned by its members, which often offers lower fees, is a credit:","union",["card","score","limit"],"Credit unions are member-owned.")
H("613.d.2.G",4,"A bank that operates only online with no branches is called a:","virtual bank",["credit union","savings bond","trust company"],"Virtual banks offer digital services.")
H("613.d.2.H",3,"Keeping bank statements, receipts, and tax forms in an organized system is part of maintaining financial:","records",["fashions","trends","debts"],"Records support taxes and planning.")
H("613.d.2.H",4,"Balancing a checkbook by comparing it with the bank statement is called:","reconciling an account",["overdrafting","investing","borrowing"],"Reconciliation catches errors.")
H("613.d.2.I",3,"A court process that helps people who cannot pay their debts is called:","bankruptcy",["probate","mortgage","audit"],"Bankruptcy is a legal remedy.")
H("613.d.2.I",4,"One way to avoid bankruptcy is to create a realistic budget and avoid taking on too much:","debt",["income","savings","interest earned"],"Controlling debt prevents financial crisis.")
H("613.d.2.J",3,"A policy that pays for damage to your car in an accident is a type of:","insurance",["loan","savings","investment"],"Insurance protects against financial loss.")
H("613.d.2.J",4,"The amount you pay out of pocket before insurance starts to pay a claim is the:","deductible",["premium","refund","interest"],"Higher deductibles lower premiums.")
H("613.d.2.K",3,"A will, a lease, and a power of attorney are examples of legal:","documents",["fashions","trends","recipes"],"Families keep important papers.")
H("613.d.2.K",4,"Documents like a birth certificate and Social Security card should be stored in a safe place such as a:","fireproof box",["glove box","trash can","kitchen drawer"],"Safe storage prevents loss.")
H("613.d.2.L",3,"A spreadsheet that automatically adds up a month's spending is an example of using technology to manage:","money",["weather","music","games"],"Software helps track finances.")
H("613.d.2.L",4,"A formula in a spreadsheet can subtract expenses from income to show:","how much is left",["how much to spend","what to buy","where to shop"],"Formulas speed calculations.")
H("613.d.3.A",3,"Before signing a lease, a renter has a responsibility to read and understand the:","terms",["rumors","colors","tastes"],"Contracts bind both sides.")
H("613.d.3.A",4,"A tenant's responsibility usually includes paying rent on time and keeping the home in:","good condition",["poor condition","random condition","no condition"],"Renters have duties and rights.")
H("613.d.3.B",3,"When buying a house, the buyer usually pays a down payment and then makes monthly mortgage:","payments",["refunds","gifts","coupons"],"Buyers finance their purchase.")
H("613.d.3.B",4,"Leasing a home generally requires less money up front than buying, but the renter builds no:","equity",["bills","savings","friends"],"Owners build equity; renters do not.")
H("613.d.3.C",3,"A person moving from renting to buying needs to save for a down payment and closing costs, which are examples of money-management:","skills",["errors","debts","penalties"],"Buying requires planning.")
H("613.d.3.C",4,"Buying a home also adds ongoing costs such as property taxes, insurance, and:","maintenance",["rent","tuition","refunds"],"Owners pay many costs.")
H("613.d.4.A",3,"Recycling and conserving water are examples of individual and family responsibility toward:","the environment",["fashion","taxes","school"],"Everyone helps protect resources.")
H("613.d.4.A",4,"A family that carpools, composts, and turns off lights is taking responsibility in relation to environmental:","trends",["fashions","recipes","games"],"Habits support sustainability.")
H("613.d.4.B",3,"Global warming, air pollution, and water shortages are environmental issues that affect families and:","future generations",["no one","past generations","stores"],"Today's choices affect tomorrow.")
H("613.d.4.B",4,"Rising sea levels and extreme weather are environmental trends linked to a changing:","climate",["menu","budget","fashion"],"Climate change affects communities.")
H("613.d.4.C",3,"Using a cloth shopping bag instead of plastic ones is a behavior that helps to:","reuse resources",["waste resources","raise trash","litter"],"Reusing conserves materials.")
H("613.d.4.C",4,"The three Rs of conservation are reduce, reuse, and:","recycle",["replace","retire","remove"],"The 3 Rs guide conservation.")
