H("613.d.4.D",4,"In the United States, a federal body that sets many pollution standards is the Environmental Protection:","Agency",["Alliance","Association","Academy"],"The EPA enforces environmental laws.")
H("613.d.5.A",3,"A law requiring clear labels on food products is a regulation that protects:","consumers",["producers","landlords","lenders"],"Regulations promote fair business.")
H("613.d.5.A",4,"Truth-in-lending laws require lenders to disclose the cost of a loan, which helps consumers compare:","credit offers",["recipes","vacations","fashions"],"Disclosure laws support informed choices.")
H("613.d.5.B",3,"Property tax, income tax, and a tax added at checkout are collected at different levels of government. A tax collected by the state or city on purchases is a:","sales tax",["income tax","property tax","estate tax"],"Sales tax is added at purchase.")
H("613.d.5.B",4,"Taxes pay for public services such as schools, roads, and:","police protection",["private clubs","vacations","coupons"],"Taxes fund government functions.")
H("613.d.6.A",3,"Comparing two jobs by looking at pay, health insurance, and vacation time is evaluating employment options including salaries and:","benefits",["rumors","habits","hobbies"],"Total compensation matters.")
H("613.d.6.A",4,"A job offering $42,000 plus health insurance may be better than one paying $43,000 with no insurance because of the value of:","benefits",["rent","fees","fines"],"Benefits add real value.")
H("613.d.6.B",3,"A higher-level job usually brings more pay and responsibility, which are the rewards and:","demands",["errors","rumors","costs"],"Higher levels carry greater responsibilities.")
H("613.d.6.B",4,"Entry-level jobs often have lower pay but may require less:","education and experience",["responsibility only","training only","work only"],"Levels differ in rewards and demands.")
H("613.d.6.C",3,"A person who loves working with people and has strong communication skills might choose a career in:","customer service",["isolated research","welding only","mining only"],"Interests and abilities guide choices.")
H("613.d.6.C",4,"A parent who needs flexible hours may weigh family responsibilities when deciding on a:","career path",["menu","school schedule","hobby"],"Priorities shape career choices.")
H("613.d.6.D",3,"Taking a night class or earning a certificate while working is continuing education that can help with career:","advancement",["decline","delay","loss"],"More training opens opportunities.")
H("613.d.6.D",4,"Employers may help pay for classes because continuing education improves employee:","skills",["debts","vacations","absences"],"Training benefits both sides.")
H("613.d.6.E",3,"Using slides, speaking clearly, and making eye contact are presentation skills used to communicate knowledge about:","careers",["recipes","weather","sports"],"Presentations share information.")
H("613.d.6.E",4,"When presenting about a career, you should explain education, duties, and:","pay and outlook",["favorite foods","pets","vacation plans"],"Complete information helps the audience.")
H("613.d.7.A",3,"A financial counselor helps clients make plans for their money. This is a role in consumer services that involves giving:","advice",["orders","fines","rumors"],"Counselors guide decisions.")
H("613.d.7.A",4,"A customer service representative handles complaints and questions, a function that helps maintain customer:","satisfaction",["debt","confusion","conflict"],"Service roles support satisfaction.")
H("613.d.7.B",3,"A person who opens a tax preparation service is pursuing an:","entrepreneurial endeavor",["employee benefit","product recall","warranty"],"Entrepreneurs start businesses.")
H("613.d.7.B",4,"Consumer services jobs may be found in banks, retail stores, insurance companies, and:","government agencies",["only farms","only factories","only mines"],"Opportunities exist in many settings.")
H("613.d.7.C",3,"Becoming a certified financial planner requires education, training, and passing an:","exam",["audition","contest","race"],"Certification has requirements.")
H("613.d.7.C",4,"Many consumer service careers require at least a high school diploma and on-the-job:","training",["vacation","retirement","rest"],"Education levels vary by job.")
H("613.d.7.D",3,"A group such as the National Association of Consumer Advocates is a professional organization that supports workers by providing:","resources and networking",["free housing","paychecks","guaranteed raises"],"Organizations offer support.")
H("613.d.7.D",4,"Joining a professional organization can help workers learn about new laws and connect with other:","professionals",["strangers","competitors only","landlords"],"Networking builds careers.")

# ---- 614 Nutrition and Wellness ----
H("614.d.1.A",3,"Carbohydrates, proteins, fats, vitamins, minerals, and water are the six classes of:","nutrients",["recipes","meals","snacks"],"Nutrients are substances the body needs.")
H("614.d.1.A",4,"Which nutrient is the body's main source of quick energy?","carbohydrates",["vitamins","minerals","water"],"Carbohydrates fuel the body.")
H("614.d.1.B",3,"Eating too little protein over time can affect muscle growth, appearance of skin and hair, and job:","performance",["parking","dress","travel"],"Nutrition affects the whole person.")
H("614.d.1.B",4,"A diet lacking iron can cause fatigue, which lowers a worker's:","energy and focus",["height","eye color","pay stub"],"Poor nutrition reduces productivity.")
H("614.d.1.C",3,"A teenager who is growing quickly generally needs more calories and calcium than a:","sedentary older adult",["marathon runner","pregnant teen","growing child"],"Needs vary by life stage.")
H("614.d.1.C",4,"Dietary guidelines for pregnant women often recommend extra folic acid to support the developing:","baby",["roommate","car","pet"],"Special needs exist across the life cycle.")
H("614.d.1.D",3,"Writing down everything you eat for three days and comparing it to MyPlate is a way to compare personal food intake to recommended dietary:","guidelines",["menus","costs","trends"],"A food record shows gaps.")
H("614.d.1.D",4,"If your food record shows few fruits and vegetables, you should adjust your diet to match the dietary:","recommendations",["rumors","habits","trends"],"Guidelines help improve eating habits.")
H("614.d.2.A",3,"The breakdown of food into small particles the body can absorb is called:","digestion",["metabolism","circulation","respiration"],"Digestion starts in the mouth.")
H("614.d.2.A",4,"The chemical processes by which the body converts food into energy are called:","metabolism",["digestion","excretion","circulation"],"Metabolism releases energy.")
H("614.d.2.B",3,"The energy the body needs at rest to keep vital organs working is its basal:","metabolism",["activity","exercise","weight"],"Basal metabolism powers basic functions.")
H("614.d.2.B",4,"Which factor can increase the number of calories a person burns each day?","regular physical activity",["sitting all day","skipping meals","extra sleep only"],"Activity raises total energy use.")
H("614.d.2.C",3,"Because the body digests starches and sugars faster than fats, a person needing quick energy before a game might choose a snack rich in:","carbohydrates",["fats","oils","butter"],"Digestion speed affects food choices.")
H("614.d.2.C",4,"Eating very large meals right before exercise may cause discomfort because the body is busy with:","digestion",["relaxation","sleep","hydration"],"Timing matters.")
H("614.d.2.D",3,"A community center, park, or YMCA is a community resource that promotes physical:","activity",["rest","debt","travel"],"Resources support wellness.")
H("614.d.2.D",4,"A city that builds walking trails is providing a resource that supports public:","fitness",["pollution","traffic","noise"],"Communities encourage active lifestyles.")
H("614.d.2.E",3,"If calories eaten exceed calories burned, a person is likely to:","gain weight",["lose weight","stay at the same weight","lose height"],"Energy balance determines weight.")
H("614.d.2.E",4,"To maintain a healthy weight, calories consumed should balance calories used in activity and:","metabolism",["sleep","hunger","thirst"],"Energy in must match energy out.")
H("614.d.3.A",3,"Eating a diet high in sugar and saturated fat over many years can increase the risk of:","heart disease",["growing taller","better hearing","stronger eyesight"],"Food choices affect long-term health.")
H("614.d.3.A",4,"Choosing whole grains over refined grains daily can have long-term benefits for:","digestive health",["tooth color","hair length","height"],"Healthy habits pay off.")
H("614.d.3.B",3,"Limiting sodium and eating more fruits and vegetables can help manage a diet-related disease such as:","high blood pressure",["a cold","a sprain","a rash"],"Diet can help control disease.")
H("614.d.3.B",4,"A strategy for preventing type 2 diabetes includes maintaining a healthy weight and limiting:","added sugars",["fiber","water","vegetables"],"Prevention relies on lifestyle.")
H("614.d.3.C",3,"A person who gets hives after eating peanuts has a food:","allergy",["preference","habit","craving"],"Allergies involve the immune system.")
H("614.d.3.C",4,"Difficulty digesting milk sugar is called lactose:","intolerance",["allergy","craving","adaptation"],"Intolerance is a digestive problem.")
H("614.d.3.D",3,"When planning meals for a very active teenager, a cook would include more:","calories",["rumors","spices","trends"],"Needs depend on activity level.")
H("614.d.3.D",4,"Using smaller plates and measuring servings are strategies for portion:","control",["growth","creation","reading"],"Portion control helps manage calories.")
H("614.d.3.E",3,"A diet that limits sodium for a person with high blood pressure is an example of a:","therapeutic diet",["fad diet","crash diet","party menu"],"Therapeutic diets treat health conditions.")
H("614.d.3.E",4,"A low-sugar, carbohydrate-controlled plan is commonly used as a therapeutic diet for people with:","diabetes",["colds","broken bones","sunburn"],"Diet is part of treatment.")
H("614.d.3.F",3,"A product claiming you'll lose 20 pounds in a week without exercise is likely a:","fad diet claim",["balanced plan","safe guideline","doctor's rule"],"Extreme claims are red flags.")
H("614.d.3.F",4,"Advertising claims about a diet should be checked against recommendations from reliable sources such as the Dietary:","Guidelines for Americans",["Fashion Review","Sports Report","Weather Service"],"Evidence-based guidelines matter.")
H("614.d.3.G",3,"Smoking, inactivity, and poor eating are lifestyle habits that can increase health:","risks",["rewards","benefits","savings"],"Habits influence health.")
H("614.d.3.G",4,"Choosing to walk daily instead of sitting for long periods is a lifestyle change that can lower the risk of:","chronic disease",["fun","savings","sleep"],"Active lifestyles protect health.")
H("614.d.3.H",3,"WIC and school meal programs are examples of community programs that provide nutrition and wellness:","services",["fines","taxes","penalties"],"Programs help families.")
H("614.d.3.H",4,"A food bank helps people who cannot afford enough food by providing:","free groceries",["fast food coupons","luxury items","cookbooks only"],"Food banks serve communities.")
H("614.d.3.I",3,"Fast food meals are often high in calories, sodium, and:","fat",["fiber","vitamins","water"],"Many fast foods are nutrient-poor.")
H("614.d.3.I",4,"A healthier fast food choice might be a grilled chicken sandwich instead of:","a deep-fried chicken sandwich",["a salad","fruit","yogurt"],"Preparation method affects nutrition.")
H("614.d.3.J",3,"The Nutrition Facts label lists serving size, calories, and amounts of:","nutrients",["colors","brand names","stores"],"Labels provide nutrition data.")
H("614.d.3.J",4,"On a food label, the percent daily value tells how much a serving contributes to a person's total:","daily diet",["bill","weight","height"],"Percent daily value compares to daily needs.")
H("614.d.3.K",3,"If a package says one serving is 1/2 cup but you eat 1 cup, you are eating how many servings?","2",["1","4","0.5"],"1 cup is two 1/2-cup servings.")
H("614.d.3.K",4,"A label lists 150 calories per serving, and the bag has 3 servings. Eating the whole bag provides:","450 calories",["150 calories","300 calories","50 calories"],"150 x 3 = 450.")
