H("614.d.3.L",4,"Compared with conventional food, organic food often costs:","more",["less","nothing","the same always"],"Organic production is often costlier.")
H("614.d.3.M",3,"Buying locally grown produce can reduce the energy used to ship food, making it a more:","sustainable choice",["costly choice only","rare choice","wasteful choice"],"Local food has a smaller footprint.")
H("614.d.3.M",4,"Reducing food waste at home benefits society by saving money and protecting:","natural resources",["wasted food","trash","landfills"],"Less waste means more resources.")
H("614.d.4.A",3,"Keeping hot foods hot and cold foods cold is a safe and sanitary practice for food:","storage and handling",["advertising","pricing","transportation"],"Temperature control prevents bacteria.")
H("614.d.4.A",4,"Raw meat should be stored on the bottom shelf of the refrigerator so juices do not contaminate:","other foods",["the shelf","the drawer","the door"],"Proper storage prevents cross-contamination.")
H("614.d.4.B",3,"Salmonella and E. coli are bacteria that cause:","food-borne illnesses",["colds","allergies","sprains"],"These bacteria spread through contaminated food.")
H("614.d.4.B",4,"Cooking poultry to a safe internal temperature of 165°F helps prevent:","food poisoning",["weight gain","dry meat","extra cost"],"Proper temperature kills bacteria.")
H("614.d.4.C",3,"Before cooking, you should wash your hands, tie back long hair, and put on a clean:","apron",["sweater","jacket","scarf"],"Good hygiene prevents contamination.")
H("614.d.4.C",4,"A person with a cut on the hand should cover it with a bandage and wear a:","glove",["bracelet","ring","watch"],"Covering cuts protects food.")
H("614.d.5.A",3,"A standard recipe lists ingredients, amounts, and step-by-step:","directions",["advertisements","prices","stores"],"Recipes provide instructions.")
H("614.d.5.A",4,"Before you begin cooking, you should read the entire recipe and gather all the:","ingredients",["guests","dishes","coupons"],"Preparation prevents mistakes.")
