H("614.d.5.C",4,"Cooking vegetables only until tender-crisp preserves color, texture, and:","nutrients",["fat","salt","calories"],"Overcooking destroys vitamins.")
H("614.d.5.D",3,"Comparing unit prices, using a shopping list, and planning meals around sales are food-buying strategies that help control:","food costs",["calories","time","nutrients"],"Planning saves money.")
H("614.d.5.D",4,"Buying in bulk saves money only if the food will be eaten before it:","spoils",["sells","ripens","cooks"],"Waste cancels savings.")
H("614.d.5.E",3,"Baking, grilling, or steaming instead of frying is a technique that reduces overall:","fat and calories",["flavor and color","protein and fiber","water and vitamins"],"Healthy cooking lowers fat.")
H("614.d.5.E",4,"Replacing sour cream with plain yogurt is a substitution that lowers:","fat",["fiber","protein","water"],"Smart swaps reduce fat.")
H("614.d.5.F",3,"Placing the fork on the left and the knife on the right is part of proper table:","setting",["recycling","repair","safety"],"Etiquette includes correct setting.")
H("614.d.5.F",4,"At a family-style meal, serving dishes are passed to the:","right",["floor","ceiling","kitchen"],"Passing in one direction keeps order.")
H("614.d.5.G",3,"Leftovers should be refrigerated within:","two hours",["two days","twelve hours","one week"],"Food left out too long grows bacteria.")
H("614.d.5.G",4,"The oldest packages of food should be placed in front and used first, which is the principle of:","first in, first out",["last in, first out","best by random","first to spoil"],"FIFO prevents waste.")
H("614.d.6.A",3,"In a foods lab, doing your share of the cleanup and listening to teammates shows cooperation and:","responsibility",["rivalry","avoidance","delay"],"Teamwork needs everyone.")
H("614.d.6.A",4,"A good team member shares tasks, communicates, and completes assigned parts so the group can finish:","on time",["late","never","separately"],"Cooperation helps teams succeed.")
H("614.d.6.B",3,"Making a checklist of tasks and a schedule helps you manage your energy and finish assignments on:","time",["accident","impulse","loan"],"Planning helps meet deadlines.")
H("614.d.6.B",4,"Doing the longest or most important task first is a practice for managing:","time and energy",["money only","space only","friends"],"Prioritizing helps efficiency.")
H("614.d.6.C",3,"When two group members disagree on a recipe, a leader might help the group find a compromise through:","teamwork",["rivalry","avoidance","blame"],"Leaders guide cooperation.")
H("614.d.6.C",4,"Solving a problem such as a missing ingredient by suggesting a substitution shows:","problem solving",["avoidance","blame","delay"],"Flexible thinking fixes issues.")
H("614.d.6.D",3,"Using visuals and clear speech to explain nutrition careers to classmates demonstrates:","presentation skills",["guessing","avoiding","reading"],"Presentations communicate knowledge.")
H("614.d.6.D",4,"Good presentation skills include speaking clearly, making eye contact, and using:","visual aids",["interruptions","long scripts","fast talking"],"Visuals help audiences understand.")
H("614.d.7.A",3,"A registered dietitian needs a college degree and an internship, while a nutrition assistant may need less. This compares the:","education or training needed",["pay only","weather","fashion"],"Careers have different requirements.")
H("614.d.7.A",4,"Which career in nutrition typically requires the most education?","registered dietitian",["cashier","stock clerk","delivery driver"],"Dietitians need advanced training.")
H("614.d.7.B",3,"Becoming a dietitian within eight years is an example of a long-term:","career goal",["mistake","habit","rumor"],"Goals guide planning.")
