H("614.d.7.C",3,"Starting a healthy meal-prep delivery service is an example of an:","entrepreneurial opportunity",["employee benefit","tax refund","warranty"],"Entrepreneurs serve market needs.")
H("614.d.7.C",4,"Before starting a nutrition-based business, an entrepreneur should identify customer needs and study the:","competition",["weather","calendar","trends of 1980"],"Market research is key.")
H("614.d.7.D",3,"The first step of a structured approach to a business challenge is to clearly identify the:","problem",["profit","solution","result"],"First define the problem.")
H("614.d.7.D",4,"After choosing a solution to a business problem, a good next step is to:","evaluate the results",["ignore it","blame others","start over randomly"],"Evaluation improves performance.")

# ---- 615 Lifetime Family Dynamics (part A) ----
H("615.d.1.A",3,"Heredity, environment, culture, and experiences are factors that shape a person's:","identity",["address","schedule","budget"],"Many forces help form personality and self-esteem.")
H("615.d.1.A",4,"Self-esteem is best described as how a person feels about his or her own:","worth",["income","height","address"],"Self-esteem is a sense of value.")
H("615.d.1.B",3,"Parents who offer praise, encouragement, and support help a child develop healthy:","self-esteem",["debts","fears","rivalries"],"Family interactions shape identity.")
H("615.d.1.B",4,"A family that sets clear values and gives love teaches children who they are. This shows the family's influence on personal:","identity",["wealth","fashion","travel"],"Family is a major influence.")
H("615.d.1.C",3,"Exercising, building friendships, and learning new skills promote physical, social, and intellectual:","development",["decline","isolation","stress"],"Growth happens in many areas.")
H("615.d.1.C",4,"Journaling, talking with a friend, or seeking counseling are strategies that promote emotional:","development",["isolation","avoidance","denial"],"Emotional growth needs attention.")
H("615.d.2.A",3,"Identifying the problem, listing options, and weighing consequences are steps in the:","decision-making process",["shopping spree","gossip chain","career fair"],"A process helps people choose wisely.")
H("615.d.2.A",4,"After choosing an option and acting on it, the last step of the decision-making process is to:","evaluate the result",["ignore it","blame others","forget it"],"Evaluation helps future choices.")
H("615.d.2.B",3,"Every decision has results, and the person who makes it is responsible for its:","outcomes",["rumors","spelling","colors"],"Decisions have consequences.")
H("615.d.2.B",4,"Choosing to skip studying for a test and failing it shows that decisions have:","consequences",["rewards only","no effects","no costs"],"Actions lead to outcomes.")
H("615.d.2.C",3,"Deciding to stay up all night may affect a teen's health, grades, and:","relationships",["height","weather","parking"],"Decisions have wide effects.")
H("615.d.2.C",4,"A decision to spend savings on a trip may reduce money available for the family's:","other needs",["entertainment only","vacation","weekend"],"Choices affect families.")
H("615.d.3.A",3,"Moving out, paying bills, and cooking for yourself are adjustments related to achieving:","independence",["dependence","immaturity","isolation"],"Independence brings change.")
H("615.d.3.A",4,"A young adult adjusting to living alone may find that the hardest changes include managing money and:","loneliness",["growth","weather","traffic"],"Independence requires adjustments.")
H("615.d.3.B",3,"Responsibilities of an independent adult include paying rent, buying groceries, and managing:","time and money",["homework","allowance","curfew"],"Adults manage their own lives.")
H("615.d.3.B",4,"An adult living independently is responsible for making sure bills are paid on:","time",["credit","trend","impulse"],"Responsibility includes meeting obligations.")
H("615.d.4.A",3,"Meeting someone, becoming friends, and building trust are early stages in the development of a:","relationship",["career","budget","hobby"],"Relationships develop over time.")
H("615.d.4.A",4,"Healthy relationships are built on trust, respect, and open:","communication",["silence","secrets","competition"],"Communication supports relationships.")
H("615.d.4.B",3,"A family that teaches children to listen, share, and cooperate fosters the ability to develop healthy:","relationships",["rivalries","habits","debts"],"Families model relationship skills.")
H("615.d.4.B",4,"Children learn how to solve conflicts by watching how the adults in their family:","handle disagreements",["pay bills","drive cars","choose jobs"],"Modeling shapes behavior.")
H("615.d.4.C",3,"Customs about who makes decisions, how elders are treated, and how affection is shown are examples of cultural:","patterns",["debts","rumors","fashions"],"Cultures shape family life.")
H("615.d.4.C",4,"In some cultures, extended families live together and share caregiving. This cultural pattern affects family:","relationships",["trends","meals","fashions"],"Culture affects roles.")
H("615.d.5.A",3,"Keeping confidences, being loyal, and showing kindness are ways to promote positive:","friendships",["rivalries","debts","habits"],"Friendships need care.")
H("615.d.5.A",4,"One way to repair a friendship after an argument is to apologize and listen to the other person's:","point of view",["secrets","complaints","gossip"],"Listening restores trust.")
H("615.d.5.B",3,"Peer pressure can lead a teen to make choices they would not make alone. A positive form is when friends encourage:","studying or volunteering",["cheating","risky behavior","skipping school"],"Peers can influence for good or bad.")
H("615.d.5.B",4,"Standing up to negative peer pressure shows strong:","self-esteem",["debt","fear","rivalry"],"Confident people choose for themselves.")
H("615.d.5.C",3,"Speaking politely and following reasonable instructions from a teacher or boss is an appropriate response to:","authority figures",["peers","strangers","pets"],"Respect for authority matters.")
H("615.d.5.C",4,"If you disagree with a supervisor's decision, an appropriate response is to calmly explain your concerns at:","an appropriate time",["any moment publicly","a party","the break room gossip"],"Respectful discussion works best.")
H("615.d.5.D",3,"Learning about different cultures and treating everyone fairly promotes an appreciation of:","diversity",["conformity","isolation","prejudice"],"Diversity enriches communities.")
H("615.d.5.D",4,"Inviting people from varied backgrounds into a club is one way to promote:","inclusion",["exclusion","bias","conflict"],"Inclusion supports belonging.")
H("615.d.6.A",3,"Teens date for reasons such as companionship and learning about relationships. Social media can both help and harm dating by affecting:","communication and privacy",["only grades","only meals","only exercise"],"Technology changes dating.")
H("615.d.6.A",4,"Sharing private photos or messages online during a relationship can create a risk to a person's:","reputation and safety",["grades only","height","weekend plans"],"Digital content can spread.")
H("615.d.6.B",3,"Commitment, respect, communication, and shared values are components of a successful:","marriage",["rivalry","contest","vacation"],"Strong marriages share these traits.")
H("615.d.6.B",4,"Couples who share responsibilities and support each other's goals tend to have stronger:","partnerships",["debts","rivalries","grudges"],"Cooperation builds marriages.")
H("615.d.6.C",3,"Using respectful words, listening, and expressing feelings calmly are communication behaviors that strengthen a:","marriage",["rivalry","debt","fad"],"Good communication builds closeness.")
H("615.d.6.C",4,"A couple who sets aside time to talk daily is practicing a communication behavior that helps them:","stay connected",["avoid conflict forever","never disagree","spend less"],"Regular talks strengthen the bond.")
H("615.d.7.A",3,"Nuclear, single-parent, blended, and extended are examples of diverse family:","structures",["budgets","menus","fashions"],"Families come in many forms.")
H("615.d.7.A",4,"A family formed when two parents with children from earlier relationships marry is a(n):","blended family",["nuclear family","single-parent family","extended family"],"Blended families combine households.")
H("615.d.7.B",3,"Some members of a household earn money, others care for children, and some help with chores. These are the functions of individuals in the:","family",["school","store","office"],"Each person contributes.")
H("615.d.7.B",4,"A teenager who babysits younger siblings is fulfilling a function within the family by providing:","care",["rivalry","income only","entertainment"],"Roles help the family run.")
H("615.d.7.C",3,"In some cultures, grandparents are central caregivers. Comparing such functions across cultures shows that family roles can:","vary",["be identical","not exist","never change"],"Cultures differ.")
H("615.d.7.C",4,"All cultures expect families to raise children and provide emotional support. This is a function shared by:","families worldwide",["only one culture","no culture","only cities"],"Some functions are universal.")
H("615.d.7.D",3,"An economic downturn with high unemployment can lead families to cut spending, which is an example of how economic trends affect:","individuals and families",["only businesses","only governments","only schools"],"Trends influence family choices.")
H("615.d.7.D",4,"As the population ages, more families will need to provide care for older adults. This is a demographic trend that predicts changes in:","family responsibilities",["school mascots","weather","music"],"Trends shape needs.")
H("615.d.7.E",3,"Making a budget so a family can pay for food, housing, and savings is a procedure for meeting needs through resource:","management",["destruction","avoidance","waste"],"Management stretches resources.")
H("615.d.7.E",4,"A family that sets goals and plans how to use time, money, and energy is practicing resource:","management",["waste","delay","guessing"],"Planning meets family needs.")
H("615.d.7.F",3,"Video calls and group chats allow distant relatives to stay in touch, showing how technology can influence family:","relationships",["debts","weather","taxes"],"Technology connects families.")
H("615.d.7.F",4,"Too much screen time at dinner can reduce face-to-face:","conversation",["homework","chores","sleep"],"Technology can also harm interaction.")
H("615.d.7.G",3,"Strong families raise capable citizens who contribute to their:","community",["competition","isolation","enemies"],"Healthy families benefit society.")
H("615.d.7.G",4,"When families function well, the community and society benefit from lower crime, better schools, and more:","volunteers",["conflict","poverty","illness"],"Good functioning has ripple effects.")

# ---- 615 part B ----
H("615.d.8.A",3,"Marriage, birth of children, children leaving home, and retirement are stages of the family life:","cycle",["tax","budget","menu"],"Families move through predictable stages.")
