H("615.d.8.D",3,"Telehealth visits and online banking are examples of technological advances that may affect older adults by making services more:","accessible",["costly","confusing only","distant"],"Technology can help families at every stage.")
H("615.d.8.D",4,"Smart devices for monitoring older relatives' health may help families give care from:","a distance",["nowhere","one room only","a school"],"Technology changes caregiving.")
H("615.d.8.E",3,"Setting screen-time rules and device-free family times is part of a plan for managing technology in:","families",["factories","schools only","stores"],"Plans balance technology use.")
H("615.d.8.E",4,"A family plan for technology might include limits on use, rules for privacy, and:","time together without devices",["unlimited gaming","secret passwords","no rules"],"Balance supports family life.")
