H("615.d.11.C",4,"Writing down specific career goals with dates helps a person turn dreams into a:","plan",["rumor","wish","guess"],"Goals need plans.")
H("615.d.12.A",3,"Speaking, body language, writing, and email are forms of verbal, nonverbal, written, and electronic:","communication",["isolation","avoidance","travel"],"Communication has many forms.")
H("615.d.12.A",4,"A professional email should have a clear subject line, correct spelling, and a polite:","tone",["slang","joke","rumor"],"Good electronic communication is professional.")
H("615.d.12.B",3,"In some cultures direct eye contact shows respect, while in others it may seem rude. This shows how cultural background can influence patterns of:","communication",["spending","dress","travel"],"Culture shapes communication.")
H("615.d.12.B",4,"A worker who learns about a coworker's cultural communication style can avoid:","misunderstandings",["cooperation","friendship","teamwork"],"Cultural awareness improves communication.")
H("615.d.12.C",3,"Compromise, listening, and respectful speech are positive interpersonal skills used in conflict:","resolution",["escalation","avoidance","denial"],"These skills solve disagreements.")
H("615.d.12.C",4,"Negotiation involves two sides working to reach an agreement that both can:","accept",["avoid","ignore","hide"],"Negotiation seeks mutual benefit.")
H("615.d.12.D",3,"Being honest with customers and following company rules are ethical practices in the:","workplace",["playground","kitchen only","bank only"],"Ethics apply at work.")
H("615.d.12.D",4,"Reporting unsafe conditions instead of hiding them is an ethical practice because it protects:","coworkers",["only managers","only profits","only visitors"],"Ethical choices protect others.")
H("615.d.12.E",3,"A team leader who helps solve a problem by listening to all ideas is using leadership and team member skills in:","problem solving",["gossip","avoidance","blame"],"Leaders and members work together.")
H("615.d.12.E",4,"Good team members contribute ideas, respect others, and help the group reach a shared:","goal",["rumor","prize alone","delay"],"Teamwork focuses on goals.")
H("615.d.13.A",3,"A job that requires frequent travel may keep a parent away from home, an example of the impact of career choice on:","family life",["weather","taxes","fashion"],"Career choices affect families.")
H("615.d.13.A",4,"Choosing a career with predictable hours may give a parent more time with:","children",["coworkers","competitors","vendors"],"Careers affect family time.")
H("615.d.13.B",3,"A worker whose family member is ill may have trouble concentrating at work, showing the effect of family life on workplace:","productivity",["fashion","parking","decor"],"Family stress affects work.")
H("615.d.13.B",4,"Supportive family relationships can improve a worker's focus and:","morale",["tardiness","absence","stress"],"Home life affects performance.")
H("615.d.13.C",3,"Flexible schedules, parental leave, and on-site child care are employment practices that support:","families",["competitors","vendors","stockholders"],"Family-friendly workplaces help employees.")
H("615.d.13.C",4,"Working from home part of the week is a trend that can help parents balance work and:","family responsibilities",["school","sports","vacation"],"Remote options support balance.")
H("615.d.13.D",3,"Remote work tools let some employees work from home, showing how technology impacts career options and family:","roles",["debts","menus","trends"],"Technology changes where and how people work.")
