H("616.d.1.G",3,"A drug dependency rehabilitation center is a social service that helps people overcome:","addiction",["boredom","hunger","fatigue"],"Rehab centers treat substance dependence.")
H("616.d.1.G",4,"A crisis hotline and a counseling center are both examples of social services that support people's:","mental health",["car repair","shopping","travel"],"Services provide help.")
H("616.d.1.H",3,"A condition in which a person has false beliefs that others are trying to harm them is called:","paranoia",["anxiety","confidence","creativity"],"Paranoia involves suspicion.")
H("616.d.1.H",4,"Which condition is characterized by hallucinations, delusions, and disorganized thinking?","schizophrenia",["a cold","a sprain","hunger"],"Schizophrenia is a serious mental disorder.")
H("616.d.2.A",3,"A health care worker notices a patient's tone of voice and gestures and adjusts the way he speaks. This is adapting communication to the patient's:","needs",["wants","jokes","wardrobe"],"Good communicators adjust their messages.")
H("616.d.2.A",4,"If a client is anxious, a calm voice and simple words are ways to:","adapt communication",["raise stress","avoid the client","ignore feelings"],"Adapting helps understanding.")
H("616.d.2.B",3,"Eliminating distractions, making eye contact, and summarizing what you heard are techniques that minimize communication:","barriers",["bridges","paths","tools"],"Listening skills reduce barriers.")
H("616.d.2.B",4,"A noisy room, a language difference, and a rushed manner are all communication:","barriers",["tools","goals","bridges"],"Barriers interfere with understanding.")
H("616.d.2.C",3,"A responsive worker listens and thinks before replying; a reactive worker responds:","without thinking",["slowly","calmly","with care"],"Responsive communication is thoughtful.")
H("616.d.2.C",4,"When a client shouts, a responsive reply is to stay calm and:","acknowledge the feelings",["shout back","walk away","argue"],"Calm responses de-escalate.")
H("616.d.3.A",3,"Psychiatrist, counselor, psychologist, and social worker are all career opportunities related to mental:","health",["wealth","fitness","travel"],"Many careers support mental wellness.")
H("616.d.3.A",4,"Which career helps people through talk therapy and may require a master's degree?","licensed counselor",["welder","pilot","accountant"],"Counselors provide therapy.")
H("616.d.3.B",3,"A group that includes a doctor, a nurse, a social worker, and a therapist working together for a patient is called a:","multidisciplinary team",["fan club","committee of one","crowd"],"Teams share expertise.")
H("616.d.3.B",4,"A benefit of the multidisciplinary team is that each member brings different:","expertise",["salaries","schedules","uniforms"],"Teamwork improves care.")
H("616.d.3.C",3,"A caregiver who thinks about how a choice will affect a patient before acting is justifying the consequences of:","decisions",["fashion","weather","payday"],"Decisions have outcomes.")
H("616.d.3.C",4,"Explaining why you chose a treatment option and what might result shows that you can justify the:","consequences",["costs only","colors","hours"],"Justification includes outcomes.")
H("616.d.3.D",3,"A trained student helps two classmates settle a disagreement by listening to both sides. This is peer:","mediation",["pressure","review","tutoring"],"Mediators help resolve conflicts.")
H("616.d.3.D",4,"Negotiation in conflict resolution aims for a result that is acceptable to:","both sides",["one side","neither side","only the mediator"],"Both parties give and gain.")
H("616.d.3.E",3,"Learning and correctly using terms such as 'anxiety,' 'diagnosis,' and 'therapy' is mastering mental health:","vocabulary",["recipes","maps","games"],"Accurate terms prevent confusion.")
H("616.d.3.E",4,"Writing a patient's symptoms clearly and accurately in a record is called:","documentation",["gossip","guessing","advertising"],"Records need precise language.")
H("616.d.3.F",3,"Individual therapy, group therapy, and medication are examples of mental health treatment:","options",["costs","crimes","games"],"Several approaches exist.")
H("616.d.3.F",4,"A treatment where several people with similar concerns meet together with a therapist is called:","group therapy",["family dinner","a lecture","a rally"],"Group therapy provides shared support.")
H("616.d.4.A",3,"Keeping a patient's information private and sharing it only with those who need it follows the principle of:","confidentiality",["publicity","curiosity","gossip"],"Privacy builds trust.")
H("616.d.4.A",4,"Sharing a client's story on social media would violate:","ethical practice",["good manners only","hospital rules","none"],"Ethics protect clients.")
H("616.d.4.B",3,"Failure to give the standard of care expected, which harms a patient, is called:","negligence",["compliance","generosity","empathy"],"Negligence is a legal issue.")
H("616.d.4.B",4,"A health care worker could be sued for malpractice if a patient is harmed because the worker:","did not follow professional standards",["followed the rules","asked questions","took notes"],"Malpractice involves failing a duty.")
H("616.d.4.C",3,"A scope of practice is the set of duties that a professional is legally allowed and trained to:","perform",["avoid","ignore","hide"],"Staying within scope protects patients.")
H("616.d.4.C",4,"A nursing assistant performing a task that only a licensed nurse is allowed to do would be going beyond the:","scope of practice",["work schedule","uniform policy","parking rules"],"Roles are defined by law.")
H("616.d.4.D",3,"Patients have the right to be informed, to refuse treatment, and to be treated with:","respect and dignity",["no information","limited care","secrecy"],"Client rights protect choice.")
H("616.d.4.D",4,"A client's right to choose may be limited if the person is a danger to self or others. This is a circumstance that can:","alter client rights",["end all rights","remove all care","cancel privacy"],"Safety can override some choices.")
H("616.d.4.E",3,"Acting out a patient who refuses medication in class helps students understand client rights through:","role-playing",["lectures only","reading only","guessing"],"Dramatizing makes cases real.")
H("616.d.4.E",4,"In a dramatized case study, students practice responding to a client's choices while protecting the client's:","rights",["lunch","wages","uniforms"],"Role-play builds understanding.")
H("616.d.4.F",3,"HIPAA is a federal law that protects the privacy of patients' health:","information",["insurance rates","hospital names","doctor salaries"],"Legislation sets standards of care.")
H("616.d.4.F",4,"Laws that require licensed professionals to report suspected abuse help set standards for:","client care",["parking","advertising","uniforms"],"Laws protect patients.")
H("616.d.4.G",3,"The Texas Department of State Health Services is a regulatory agency that sets and enforces rules for health:","care",["fashion","travel","sports"],"Agencies regulate care.")
H("616.d.4.G",4,"A regulatory agency may inspect facilities and take action against a provider that does not meet:","standards",["wishes","trends","hobbies"],"Agencies enforce rules.")
H("616.d.5.A",3,"Unexplained bruises and fearful behavior may be signs of an abusive:","situation",["holiday","meal","game"],"Workers must recognize abuse.")
H("616.d.5.A",4,"A health care worker who suspects abuse is generally required by law to:","report it",["ignore it","gossip","wait a year"],"Mandatory reporting protects victims.")
H("616.d.5.B",3,"Staff members who stay calm when a patient suddenly becomes agitated are able to anticipate and adapt to changing:","situations",["weather","menus","schedules only"],"Flexibility is a key skill.")
H("616.d.5.B",4,"A patient's mood can change quickly, so a worker must be prepared to:","adjust the approach",["follow a script only","leave","ignore it"],"Adaptation improves care.")
H("616.d.5.C",3,"If a patient collapses, an appropriate emergency action is to call for help and begin:","first aid or CPR if trained",["a conversation","paperwork","lunch"],"Emergencies require quick action.")
H("616.d.5.C",4,"In an emergency, health care workers should follow the facility's emergency:","procedures",["gossip","menus","fashion"],"Plans guide response.")
H("616.d.5.D",3,"Washing hands, wearing gloves, and using safe lifting techniques practice personal and client:","safety",["fashion","marketing","speed"],"Safety protects everyone.")
H("616.d.5.D",4,"Keeping walkways clear and spills cleaned up helps ensure the safety of both workers and:","clients",["visitors only","managers only","vendors only"],"Safe environments prevent injury.")
H("616.d.6.A",3,"Patient charts, lab results, and billing records are examples of health care:","data",["gossip","menus","fashion"],"Data guides care.")
H("616.d.6.A",4,"Health care data must be collected and shared in ways that protect patient:","privacy",["profit","speed","fashion"],"Dissemination follows rules.")
H("616.d.6.B",3,"Blood pressure cuffs, thermometers, and computers are examples of equipment used in delivering mental health and health:","services",["recipes","games","fashions"],"Equipment supports service delivery.")
H("616.d.6.B",4,"Grouping devices by their purpose, such as monitoring or recording, is how you:","classify equipment",["destroy equipment","ignore equipment","avoid equipment"],"Classifying organizes knowledge.")
H("616.d.6.C",3,"A student should use technology only at the level their training allows, which is employing technology consistent with their:","level of training",["salary","address","schedule"],"Training sets limits.")
H("616.d.6.C",4,"A trainee who is not certified to operate a device should not use it without:","supervision",["music","speed","food"],"Use technology within training.")

